var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City not loaded"); return; }

var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel panel = null;
foreach (var r in roots) {
    panel = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (panel != null) break;
}
if (panel == null) { Debug.LogError("panel null"); return; }

var card = panel.transform.Find("Modal/Card");
if (card == null) { Debug.LogError("card null"); return; }

var rating    = card.Find("Rating");
var score     = card.Find("Score");
var breakdown = card.Find("Breakdown");
var close     = card.Find("Close");
if (rating == null || score == null || breakdown == null || close == null) {
    Debug.LogError("missing children"); return;
}

// 1) Create Sort View GO under Card
var sortViewGO = new UnityEngine.GameObject("Sort View", typeof(UnityEngine.RectTransform), typeof(UnityEngine.UI.VerticalLayoutGroup));
sortViewGO.transform.SetParent(card, false);
var sortRT = (UnityEngine.RectTransform)sortViewGO.transform;
sortRT.anchorMin = new UnityEngine.Vector2(0,0); sortRT.anchorMax = new UnityEngine.Vector2(1,1);
sortRT.sizeDelta = UnityEngine.Vector2.zero;
var sortVLG = sortViewGO.GetComponent<UnityEngine.UI.VerticalLayoutGroup>();
sortVLG.childControlWidth = true; sortVLG.childControlHeight = false;
sortVLG.childForceExpandWidth = true; sortVLG.childForceExpandHeight = false;
sortVLG.spacing = 8f;

// 2) Reparent Rating/Score/Breakdown under Sort View
rating.SetParent(sortViewGO.transform, false);
score.SetParent(sortViewGO.transform, false);
breakdown.SetParent(sortViewGO.transform, false);

// 3) Add SortResultView and wire its fields via SerializedObject
var sortView = sortViewGO.AddComponent<Sim.Jobs.SortResultView>();
var soSort = new UnityEditor.SerializedObject(sortView);
soSort.Update();
soSort.FindProperty("ratingLabel").objectReferenceValue = rating.GetComponent<TMPro.TMP_Text>();
soSort.FindProperty("scoreLabel").objectReferenceValue = score.GetComponent<TMPro.TMP_Text>();
soSort.FindProperty("breakdownLabel").objectReferenceValue = breakdown.GetComponent<TMPro.TMP_Text>();
soSort.ApplyModifiedProperties();

// 4) Create Time View GO under Card
var timeViewGO = new UnityEngine.GameObject("Time View", typeof(UnityEngine.RectTransform), typeof(UnityEngine.UI.VerticalLayoutGroup));
timeViewGO.transform.SetParent(card, false);
var timeRT = (UnityEngine.RectTransform)timeViewGO.transform;
timeRT.anchorMin = new UnityEngine.Vector2(0,0); timeRT.anchorMax = new UnityEngine.Vector2(1,1);
timeRT.sizeDelta = UnityEngine.Vector2.zero;
var timeVLG = timeViewGO.GetComponent<UnityEngine.UI.VerticalLayoutGroup>();
timeVLG.childControlWidth = true; timeVLG.childControlHeight = false;
timeVLG.childForceExpandWidth = true; timeVLG.childForceExpandHeight = false;
timeVLG.spacing = 8f;

// 5) Duplicate Rating and Score under Time View
var ratingTimeGO = UnityEngine.Object.Instantiate(rating.gameObject, timeViewGO.transform);
ratingTimeGO.name = "Rating";
var durationGO = UnityEngine.Object.Instantiate(score.gameObject, timeViewGO.transform);
durationGO.name = "Duration";

// 6) Add TimeResultView and wire fields
var timeView = timeViewGO.AddComponent<Sim.Jobs.TimeResultView>();
var soTime = new UnityEditor.SerializedObject(timeView);
soTime.Update();
soTime.FindProperty("ratingLabel").objectReferenceValue = ratingTimeGO.GetComponent<TMPro.TMP_Text>();
soTime.FindProperty("durationLabel").objectReferenceValue = durationGO.GetComponent<TMPro.TMP_Text>();
soTime.ApplyModifiedProperties();

// 7) Move Close button to last sibling so it stays at bottom
close.SetAsLastSibling();

// 8) Clear deprecated serialized fields on the panel and let views auto-fill
var soPanel = new UnityEditor.SerializedObject(panel);
soPanel.Update();
var viewsProp = soPanel.FindProperty("views");
viewsProp.ClearArray();
viewsProp.InsertArrayElementAtIndex(0);
viewsProp.GetArrayElementAtIndex(0).objectReferenceValue = sortView;
viewsProp.InsertArrayElementAtIndex(1);
viewsProp.GetArrayElementAtIndex(1).objectReferenceValue = timeView;
var fallbackProp = soPanel.FindProperty("fallbackView");
if (fallbackProp != null) fallbackProp.objectReferenceValue = sortView;
soPanel.ApplyModifiedProperties();

UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);

Debug.Log("[Restructure] sortView=" + sortView.GetInstanceID() + " timeView=" + timeView.GetInstanceID() + " — scene saved.");
